#!/usr/bin/env python3
"""Builds docs/design/SKILLS_APPLIED_PROOF.md. Every quote is asserted to be a verbatim substring of the skill file, or the script fails."""
import pathlib, sys
R = pathlib.Path(__file__).resolve().parent.parent
S = R / ".agents/skills"
def q(skill, file, quote, how):
    t = (S / skill / file).read_text()
    assert quote in t, f"quote not found in {skill}/{file}: {quote}"
    return f"**{skill}** (`.agents/skills/{skill}/{file}`)\n> {quote}\n\n*Applied:* {how}\n"
items = [
 q("improve-ui","SKILL.md","Preserve the product's identity, reuse existing owners, and prefer no finding to an unsupported one.","Kept the Luminos data layer (locker, theme tokens, skin catalog) and replaced only the screens; each round critique below cites a rendered defect, not a taste."),
 q("improve-ui","SKILL.md","Never modify product source. Create or edit files only under `design-plans/`.","This skill is read-only by design. It was used as an audit lens only; all edits were made by this session's own workflow, not by the skill."),
 q("better-layout","SKILL.md","Space groups first, background shapes second, separator lines last and only where space alone can't carry the structure.","Zero wireframe borders: rows and cards are filled surfaces, 20-28px gaps between groups, no divider lines."),
 q("better-layout","SKILL.md","Size text containers with `max-width` and `min-height`, never a fixed width or height, and let rows wrap.","Preference rows use `min-height: 68px` and wrap long copy. Mod and cosmetic cards keep the fixed 160px / 215px heights the brief specifies, with truncating labels."),
 q("better-layout","SKILL.md","Give each view one primary action.","Home has one filled Launch Game button; version and Host World are quiet secondaries."),
 q("better-motion","SKILL.md","Keystrokes, row hovers and the content behind a tab change instantly, or with a transition of `150ms` or less on `opacity` or `background-color`.","Screen change is a 120ms opacity fade; card and nav hovers are 140ms background/colour transitions."),
 q("better-motion","SKILL.md","Modals, drawers and panels | `350ms`–`450ms`","The module settings drawer slides in at 350ms on `cubic-bezier(0.2, 0, 0, 1)`; modals take 250ms."),
 q("taste-skill","SKILL.md","**Equal left and right content edges.**","Every page sits in one centred 1200px column with equal 40px side padding (`components/Page.tsx`)."),
 q("taste-skill","SKILL.md","**One system:**","One button pair (`btn-primary`, `btn-quiet`), one card surface, one radius scale, one pill style across all screens."),
 q("audit-ai-design-slop","SKILL.md","Do not guess whether AI made the design.","The critiques cite concrete defects (squashed buttons, clipped art), never origin."),
 q("audit-ai-design-slop","SKILL.md","Flag combinations of glow, gradient text, glass, borders, shadows, grids, particles, beams, noise, floating shapes, or browser chrome when multiple layers perform the same decorative job or compete with the content.","No glass, glow stacks or gradient text in the app; the only gradient is the hero legibility scrim."),
]
extra = ["better-ui","impeccable","improve-animations","ui-ux-pro-max"]
notes = []
for s in extra:
    p = S / s
    files = sorted(x.name for x in p.iterdir()) if p.exists() else []
    notes.append(f"- `{s}`: " + (f"present at `.agents/skills/{s}/` ({', '.join(files[:6])})" if files else "not present locally"))
notes.append("- `rea` and `agent-reach`: present as directories (`.agents/skills/rea/`, `.agents/skills/agent-reach/`). `npx ui-skills get rea` and `get agent-reach` print `Skill not found` (they are not in the ui-skills registry), so they were read from the local directories instead.")
comp = (R/"docs/design/COMPETITOR_REA_AUDIT.md").read_text().split("\n")[:60]
doc = ["# Skills applied (v2.0.0)", "",
 "Generated by `scripts/gen-skills-proof.py`. The script fails if a quote below is not a verbatim substring of the skill file.", "",
 "## 1. Terminal output (verbatim)", "", "Full output of `ls -la .agents/skills/` and `npx -y ui-skills@latest list` is saved in `docs/design/skills-ls-v2.txt`. First lines:", "", "```", *(R/"docs/design/skills-ls-v2.txt").read_text().split("\n")[:50], "```", "",
 "`ui-skills get <name>` prints the skill text and does not write files, so improve-ui, impeccable, better-ui, better-layout, better-motion, improve-animations and audit-ai-design-slop were saved to `.agents/skills/<name>/SKILL.md` and read from there.", "",
 "## 2. Rules quoted and how each was applied", ""] + items + ["## 3. Other skills", ""] + notes + ["",
 "## 4. Competitor breakdown (rea + agent-reach lens)", "",
 "**Honest status:** agent-reach could not fetch live pages from this sandbox session, so this section is carried from the repository's existing audit `docs/design/COMPETITOR_REA_AUDIT.md` and `.agents/context/research/onelauncher-teardown.md`, written in an earlier session. It was not re-verified today. Its opening lines:", "", "```md", *comp, "```", "",
 "Architecture takeaways used in v2: OneClient/OneConfig = module cards in a 4-column grid with a solid on/off bar and a side settings panel (Mods screen); store.polyfrost.org = a calm 3-column cosmetic grid with an equip bar (Cosmetics); xyrios skins = shaded 64×64 skins with a populated outer layer (12 built-in skins, checked by `verify-skins.mjs`); Th0rgal/shard = content-addressed storage with dedup (Preferences → Storage & Dedup, backed by existing `dedup_*` commands); ElyPrismLauncher = Ely.by through authlib-injector (Account switcher).", "",
 "## 5. Render rounds and what changed", "",
 "- **Round 1 (first render):** Launch / version / Host World buttons squashed; Hold/Toggle and Max FPS pills squashed (cause: unlayered `button { padding: 0 }` beat Tailwind utilities); skin art overflowed Cosmetics cards over the Equip bar; HUD dimension pill clipped; site showed the old v1.0.0 UI.",
 "- **Round 2:** element resets moved into `@layer base`; card stage made absolute with `max-h-full`; 3D stage zoom raised; HUD canvas top-aligned. Quickplay banners were still blurry and the wings clipped.",
 "- **Round 3:** sharp Quickplay banners; 3D zoom reduced so wings fit; HUD readout bar, 5px arrow-key nudge and a side-placed dimension pill (it overlapped CPS); theme card captions; Preferences caption and storage note; site tour and screenshots replaced with the v2 UI.",
]
(R/"docs/design/SKILLS_APPLIED_PROOF.md").write_text("\n".join(doc)+"\n")
print("wrote", len(doc), "lines")
